// Generic deterministic load fixture; contains no company RTL.
const C=require('../../src/assembly-core'),W=require('../../src/workbook');
module.exports=function(n=8,k=8){const p=C.newProject();p.top='PerfTop';p.modules=[{id:'cell',name:'PerfCell',parameters:[],ports:Array.from({length:k},(_,j)=>['input','output'].map((d,i)=>({id:d+j,name:(i?'out':'in')+'_p'+j,direction:d,range:'[7:0]',signed:false}))).flat(),interfaceOnly:true,placeholder:true}];p.instances=Array.from({length:n},(_,i)=>({id:'u'+i,name:'u_cell_p'+i,module:'PerfCell',parameters:{}}));p.nets=[];p.connections=[];p.assigns=[];p.rtlSources=[];for(let i=0;i<=n;i++)for(let j=0;j<k;j++){const name='link_'+i+'_p'+j;p.nets.push({id:name,name,range:'[7:0]',direction:i===0?'input':i===n?'output':'wire',signed:false});if(i<n)p.connections.push({id:'i'+i+'_'+j,instance:'u'+i,port:'in_p'+j,expr:name});if(i>0)p.connections.push({id:'o'+i+'_'+j,instance:'u'+(i-1),port:'out_p'+j,expr:name});}const q=W.normalize(p);q.workbook.graphPositions=Object.fromEntries(q.instances.map((i,n)=>[i.id,{x:800+(n%4)*850,y:160+Math.floor(n/4)*(k*45+240)}]));return q;};
